            Click me
          </button>
        </Slot>
      );
    }

    render(<App />);
    act(() => bump());
    act(() => bump());
    // Slot has no forwardedRef, so the child's own stable ref is passed straight through
    // (never wrapped in a composed ref). Because its identity stays stable across re-renders,
    // it is attached exactly once and receives the DOM node.
    expect(childRef).toHaveBeenCalledTimes(1);
    expect(childRef).toHaveBeenCalledWith(expect.any(HTMLButtonElement));
  });
});

