import * as React from 'react';
import { render, cleanup } from '@testing-library/react';
import { afterEach, describe, it, expect } from 'vitest';
import { Menu, MenuSub, MenuSubTrigger, MenuSubContent, MenuItem } from './menu';

describe('MenuSubTrigger composed ref stability', () => {
  afterEach(cleanup);

  it('does not cause an infinite render loop when the sub trigger ref triggers a state update', () => {
    expect(() =>
      render(
        <Menu>
          <MenuSub>
            <MenuSubTrigger>Sub</MenuSubTrigger>
            <MenuSubContent>
              <MenuItem>Item</MenuItem>
            </MenuSubContent>
          </MenuSub>
        </Menu>,
      ),
    ).not.toThrow();
  });
});

