import * as React from 'react';
import { render, cleanup } from '@testing-library/react';
import { afterEach, describe, it, expect } from 'vitest';
import { DropdownMenu, DropdownMenuTrigger, DropdownMenuContent, DropdownMenuItem } from './dropdown-menu';

describe('DropdownMenuTrigger composed ref stability', () => {
  afterEach(cleanup);

  it('does not cause an infinite render loop when attaching the ref triggers a render', () => {
    let renderCount = 0;

    function App() {
      renderCount++;
      const [, forceRender] = React.useReducer((c) => c + 1, 0);
      const ref = React.useCallback((node: HTMLElement | null) => {
        if (node) forceRender();
      }, []);

      return (
        <DropdownMenu>
          <DropdownMenuTrigger ref={ref}>Edit</DropdownMenuTrigger>
          <DropdownMenuContent>
            <DropdownMenuItem>Copy</DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      );
    }

    expect(() => render(<App />)).not.toThrow();
    expect(renderCount).toBeLessThan(25);
  });
});

